def max_k(n):
    h = n // 2
    min_val = float('inf')
    for a in range(h + 1):
        for b in range(h + 1):
            for c in range(h + 1):
                for d in range(h + 1):
                    denominator = a - b - c + d
                    if denominator > 0:
                        numerator = (a + b) * (n - (c + d))
